package com.android.launcher3.qsb;
import android.content.Context;import android.database.ContentObserver;import android.os.*;import android.provider.Settings;import android.util.Log;import java.lang.ref.WeakReference;import java.util.WeakHashMap;
public final class BlurModePreferences {
 static final WeakHashMap<Object,Watcher> watchers=new WeakHashMap<>();
 public static void attach(Object fragment){detach(fragment);try{Context c=(Context)fragment.getClass().getMethod("getContext").invoke(fragment);Object preference=fragment.getClass().getMethod("findPreference",CharSequence.class).invoke(fragment,"pref_qsb_outer_opacity");if(c==null||preference==null)return;Watcher w=new Watcher(c,preference);watchers.put(fragment,w);c.getContentResolver().registerContentObserver(Settings.System.getUriFor("lunatik_blur_mode"),false,w);w.update();}catch(Exception e){Log.w("BlurModePreferences","attach",e);}}
 public static void detach(Object fragment){Watcher w=watchers.remove(fragment);if(w!=null)w.context.getContentResolver().unregisterContentObserver(w);}
 static final class Watcher extends ContentObserver{final Context context;final WeakReference<Object> preference;final CharSequence originalSummary;Watcher(Context c,Object p)throws Exception{super(new Handler(Looper.getMainLooper()));context=c;preference=new WeakReference<>(p);originalSummary=(CharSequence)p.getClass().getMethod("getSummary").invoke(p);}public void onChange(boolean self){update();}void update(){Object p=preference.get();if(p==null)return;try{int mode=Settings.System.getInt(context.getContentResolver(),"lunatik_blur_mode",Settings.System.getInt(context.getContentResolver(),"lunatik_notification_glass",1)!=0?3:2);boolean locked=mode==3;boolean ru=context.getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ru");p.getClass().getMethod("setEnabled",boolean.class).invoke(p,!locked);CharSequence summary=locked?(ru?"Недоступно в режиме «Все эффекты размытия». Прозрачность задаётся в настройках размытия системы.":"Unavailable in All blur effects mode. Transparency is controlled by the system blur settings."):originalSummary;p.getClass().getMethod("setSummary",CharSequence.class).invoke(p,summary);}catch(Exception e){Log.w("BlurModePreferences","update",e);}}}
}
